/** Sentences that fit almost any task. */
export const EMAIL_SENTENCES = [{"group":"WÜNSCHE UND BITTEN","en":"wishes and requests","items":[{"de":"Ich möchte ...","en":"I would like ..."},{"de":"Ich brauche ...","en":"I need ..."},{"de":"Ich suche ...","en":"I am looking for ..."},{"de":"Ich interessiere mich für ...","en":"I am interested in ..."},{"de":"Ich habe eine Frage.","en":"I have a question."},{"de":"Ich habe ein Problem.","en":"I have a problem."},{"de":"Können Sie mir das bitte bestätigen?","en":"Could you please confirm this?"},{"de":"Können Sie das bitte reparieren?","en":"Could you please repair that?"}]},{"group":"FRAGEN","en":"asking for details","items":[{"de":"Wie viel kostet ...?","en":"How much does ... cost?"},{"de":"Wann beginnt ...?","en":"When does ... start?"},{"de":"Wann kann ich kommen?","en":"When can I come?"},{"de":"Um wie viel Uhr kann ich kommen?","en":"At what time can I come?"},{"de":"Wo ist ...?","en":"Where is ...?"},{"de":"Wo kann ich ... kaufen?","en":"Where can I buy ...?"},{"de":"Wie ist die Adresse?","en":"What is the address?"},{"de":"Wie kann ich mich anmelden?","en":"How can I register?"}]},{"group":"EINLADEN UND VORSCHLAGEN","en":"inviting and suggesting","items":[{"de":"Ich lade dich ein.","en":"I invite you."},{"de":"Ich möchte dich einladen.","en":"I would like to invite you."},{"de":"Kommst du bitte mit?","en":"Will you come along?"},{"de":"Können wir zusammen ... gehen?","en":"Can we go ... together?"},{"de":"Wir treffen uns um 18 Uhr.","en":"We are meeting at 6 p.m."},{"de":"Ich komme gern.","en":"I would be happy to come."}]},{"group":"DANKEN UND GRATULIEREN","en":"thanking and congratulating","items":[{"de":"Vielen Dank!","en":"Many thanks!"},{"de":"Herzlichen Dank für deine Hilfe.","en":"Many thanks for your help."},{"de":"Herzlichen Glückwunsch zum Geburtstag!","en":"Happy birthday!"},{"de":"Herzlichen Glückwunsch zur Prüfung!","en":"Congratulations on the exam!"},{"de":"Ich wünsche dir alles Gute.","en":"I wish you all the best."},{"de":"Es tut mir leid.","en":"I am sorry."}]}];

/** Word order and the grammar Teil 2 is marked on. */
export const EMAIL_GRAMMAR = [{"group":"SATZBAU","en":"word order","rows":[{"pattern":"Verb an Position 2","ruleDe":"Im Aussagesatz steht das Verb immer an Position 2.","ruleEn":"In a statement the verb is always the second element.","exampleDe":"Am Samstag komme ich um 8 Uhr.","exampleEn":"On Saturday I am coming at 8 o'clock."},{"pattern":"W-Frage","ruleDe":"Fragewort, dann Verb, dann Person.","ruleEn":"Question word, then the verb, then the person.","exampleDe":"Wann beginnt der Kurs?","exampleEn":"When does the course start?"},{"pattern":"Ja/Nein-Frage","ruleDe":"Verb zuerst, dann Person.","ruleEn":"Verb first, then the person. No question word.","exampleDe":"Haben Sie am Freitag Zeit?","exampleEn":"Do you have time on Friday?"},{"pattern":"Zeit vor Ort","ruleDe":"Erst wann, dann wo.","ruleEn":"Say when before where, the opposite of English.","exampleDe":"Ich fahre am Montag nach Berlin.","exampleEn":"I am going to Berlin on Monday."},{"pattern":"weil","ruleDe":"Das Verb geht ans Satzende. Komma nicht vergessen.","ruleEn":"weil sends the verb to the end of the clause. Do not forget the comma.","exampleDe":"Ich kann nicht kommen, weil ich arbeiten muss.","exampleEn":"I cannot come because I have to work."},{"pattern":"denn","ruleDe":"Nach denn bleibt die normale Wortstellung.","ruleEn":"After denn the word order stays normal, verb in position 2.","exampleDe":"Ich bin froh, denn die Prüfung war schwer.","exampleEn":"I am happy, because the exam was hard."}]},{"group":"VERBEN","en":"verbs","rows":[{"pattern":"möchten + Infinitiv","ruleDe":"Der Infinitiv steht am Satzende.","ruleEn":"möchten takes position 2, the infinitive goes to the end.","exampleDe":"Ich möchte einen Deutschkurs besuchen.","exampleEn":"I would like to attend a German course."},{"pattern":"können + Infinitiv","ruleDe":"Der Infinitiv steht am Satzende.","ruleEn":"können takes position 2, the infinitive goes to the end.","exampleDe":"Kann ich bitte später kommen?","exampleEn":"Can I please come later?"},{"pattern":"müssen + Infinitiv","ruleDe":"Der Infinitiv steht am Satzende.","ruleEn":"müssen takes position 2, the infinitive goes to the end.","exampleDe":"Ich muss meine Tochter zur Schule bringen.","exampleEn":"I have to take my daughter to school."},{"pattern":"Trennbare Verben","ruleDe":"Das Präfix geht ans Satzende.","ruleEn":"The prefix splits off and moves to the end of the sentence.","exampleDe":"Ich lade dich ein. Der Zug fährt um 8 Uhr ab.","exampleEn":"I invite you. The train leaves at 8."},{"pattern":"helfen, gefallen, danken","ruleDe":"Diese Verben brauchen den Dativ.","ruleEn":"These verbs take the dative: mir, dir, Ihnen, never mich or dich.","exampleDe":"Können Sie mir helfen? Die Arbeit gefällt mir.","exampleEn":"Can you help me? I like the job."}]},{"group":"FÄLLE UND PRÄPOSITIONEN","en":"cases and prepositions","rows":[{"pattern":"seit, mit, bei, zu, nach, von","ruleDe":"Nach diesen Wörtern steht immer der Dativ.","ruleEn":"These prepositions are always followed by the dative.","exampleDe":"seit einer Woche · mit dem Bus · zum Arzt","exampleEn":"for a week · by bus · to the doctor"},{"pattern":"für, ohne, um","ruleDe":"Nach diesen Wörtern steht immer der Akkusativ.","ruleEn":"These prepositions are always followed by the accusative.","exampleDe":"für dich · für zwei Wochen · ohne meinen Bruder","exampleEn":"for you · for two weeks · without my brother"},{"pattern":"Richtung oder Ort","ruleDe":"Richtung mit Akkusativ, Ort mit Dativ.","ruleEn":"Movement takes the accusative, staying in a place takes the dative.","exampleDe":"ins Kino gehen · im Kino sein","exampleEn":"to go to the cinema · to be at the cinema"}]},{"group":"VERNEINUNG UND ZEIT","en":"negation and time","rows":[{"pattern":"kein oder nicht","ruleDe":"kein steht vor einem Nomen, nicht negiert alles andere.","ruleEn":"Use kein before a noun, nicht for everything else.","exampleDe":"Ich habe keine Zeit. Ich komme nicht.","exampleEn":"I have no time. I am not coming."},{"pattern":"Tage, Monate, Uhrzeit","ruleDe":"Tage mit am, Monate mit im, Uhrzeit mit um.","ruleEn":"am for days, im for months and seasons, um for clock times. 3","exampleDe":"am Montag · im August · um 8 Uhr Schreiben Teil 2 · E-Mails","exampleEn":"on Monday · in August · at 8 o'clock"}]}];

export const emailTaskById = (id) => EMAIL_TASKS.find((t) => t.id === Number(id)) || null;
